/** The inline post view: a poster for today's hunt with one job — get them in. */
import { requestExpandedMode } from '@devvit/web/client';
import { fetchState } from './api.ts';
import { mountArt, qs } from './ui.ts';

const playBtn = qs<HTMLButtonElement>('play-btn');
const chips = qs<HTMLDivElement>('chips');
const blurb = qs<HTMLParagraphElement>('blurb');

mountArt(qs<HTMLDivElement>('hero-art'));

playBtn.addEventListener('click', event => {
  try {
    requestExpandedMode(event, 'game');
  } catch (err) {
    // Only throws outside a Reddit host (e.g. the offline preview file).
    console.error('could not expand', err);
  }
});

async function init(): Promise<void> {
  try {
    const { player, stats } = await fetchState();
    qs('dayno').textContent = `#${player.number}`;

    const chipList: string[] = [];
    chipList.push(
      player.streak > 0
        ? `<span class="chip flame">🔥 <b>${player.streak}</b>-day streak</span>`
        : `<span class="chip">🕯️ ${player.candles} candles</span>`,
    );
    if (stats.plays > 0) {
      chipList.push(
        `<span class="chip"><b>${Math.round(stats.catchRate * 100)}%</b> caught it today</span>`,
      );
    } else {
      chipList.push(`<span class="chip"><b>7×7</b> mansion</span>`);
    }
    chips.innerHTML = chipList.join('');

    if (player.status === 'caught') {
      blurb.textContent = `You caught today's ghost in ${player.probes.length}/${player.candles} candles. Tomorrow's ghost is already restless.`;
      playBtn.textContent = 'See the board';
    } else if (player.status === 'fled') {
      blurb.textContent = `Today's ghost got away. The same ghost waits for everyone until 00:00 UTC.`;
      playBtn.textContent = 'See the board';
    } else if (player.candlesLeft < player.candles) {
      blurb.textContent = `${player.candlesLeft} candle${player.candlesLeft === 1 ? '' : 's'} left today. Finish the hunt.`;
      playBtn.textContent = 'Back to the hunt';
    }
  } catch {
    // Offline or logged out: the static poster copy still reads fine.
  }
}

void init();
